def choose_next(cur, left, tau, eta, alpha, beta, rng):
    """Правило вибору мурахи: P(cur→j) ∝ tau[cur, j]^alpha · eta[cur, j]^beta серед невідвіданих."""
    left = np.asarray(left)
    w = tau[cur, left] ** alpha * eta[cur, left] ** beta   # ваги кандидатів (чисельник формули)
    c = np.cumsum(w)                                  # «рулетка»: сектори завширшки w, разом c[-1] = знаменник
    if not np.isfinite(c[-1]) or c[-1] <= 0:          # усі ваги 0 або переповнення — рівноймовірно
        return int(rng.choice(left))
    k = np.searchsorted(c, rng.random() * c[-1], side='right')   # куди впала кулька: P(k) = w[k] / сума
    return int(left[min(k, len(left) - 1)])
